import {cli, Strategy} from '@jackwener/opencli/registry';
import {ArgumentError, CliError} from '@jackwener/opencli/errors';
import {navigate, checkProblem, withPageActivity} from './browser-utils.js';
import {flightArgs, validateFlightArgs} from './flight-probes.js';

export function qunarFlightUrl(args) {
  validateFlightArgs(args);
  if(args.from!=='SHA'||args.to!=='SEL')throw new ArgumentError('Only Shanghai to Seoul has been resolved on Qunar mobile web');
  const url=new URL('https://touch.qunar.com/ncs/page/interlist');
  // Generated by the official touch form after selecting both all-airport cities,
  // Jan 8, two adults and zero children. This is distinct from the desktop portal.
  for(const [key,value] of Object.entries({depCity:'上海',arrCity:'首尔',goDate:args.date,from:'touch_index_search',
    adult:args.adults,child:0,cabinType:0,flightType:'oneWay'}))url.searchParams.set(key,String(value));
  return url.toString();
}

export function qunarFlightRequest(entries) {
  for(const entry of entries) {
    if(!entry.captureComplete||entry.responseStatus!==200||new URL(entry.url).pathname!=='/flight/api/touchInterList')continue;
    let request;try{request=JSON.parse(entry.requestBodyPreview);}catch{continue;}
    if(!request||typeof request!=='object')continue;
    const count=value=>/^\d$/.test(String(value))?Number(value):null;
    // Only business query fields leave the network capture. No response body,
    // authentication data or opaque platform payload is persisted or decoded.
    return {origin_text:request.depCity,destination_text:request.arrCity,date:request.goDate,
      adults:count(request.adult),children:count(request.child),infants:count(request.infant)};
  }
  return null;
}

function readQunarFlight() {
  const text=selector=>document.querySelector(selector)?.innerText.trim()||null;
  return {host:location.hostname,path:location.pathname,trip:new URL(location.href).searchParams.get('flightType'),
    routeText:text('#flightList .page-title'),date:document.querySelector('.date-content .item.active')?.getAttribute('data-d')||null,
    priceLabel:text('.time-tip-text-right'),timeLabels:text('.left-tip'),
    serviceNotice:document.querySelector('#app')?.innerText.split('\n').find(t=>t.startsWith('服务调整通知'))||null,
    cards:[...document.querySelectorAll('.list-content > .list-row.item')].map(card=>{
      const txt=selector=>card.querySelector(selector)?.innerText.trim()||null;
      const offset=txt('.add-day'),arrival=txt('.to-time');
      return {priceRaw:txt('.price1 .price-info'),airline:txt('.company-name'),flightNos:[],
        departureTime:txt('.from-time'),arrivalTime:arrival?[arrival,offset].filter(Boolean).join(' '):null,
        departureAirport:txt('.from-place'),arrivalAirport:txt('.to-place'),duration:txt('.inter-howlong .time'),
        stopoverText:txt('.stop-city'),cabin:txt('.cabin-info')};
    })};
}

export function mapQunarFlight(state,request,args,url) {
  if(state.host!=='touch.qunar.com'||state.path!=='/ncs/page/interlist'||state.trip!=='oneWay')
    throw new CliError('PROVIDER_ERROR','Qunar redirected away from the mobile one-way flight list');
  if(state.priceLabel!=='人均含税价')throw new CliError('UNVERIFIED_RESPONSE','Qunar per-traveler tax label could not be verified');
  const observedSearch={origin:state.routeText?.startsWith('上海')&&request?.origin_text==='上海'?'SHA':null,
    destination:state.routeText?.endsWith('首尔')&&request?.destination_text==='首尔'?'SEL':null,
    date:state.date===request?.date?state.date:null,adults:request?.adults??null,children:request?.children??null,infants:request?.infants??null};
  return state.cards.filter(c=>/^\d+(?:\.\d{1,2})?$/.test(c.priceRaw||'')).slice(0,Number(args.limit)).map(card=>({...card,
    schema:'flight-observation-v1',price:card.priceRaw,priceState:'exact_display',priceBasis:'listed_per_traveler_tax_inclusive_fare',
    priceLabel:state.priceLabel,taxesLabel:state.priceLabel,listedTaxesIncluded:true,currency:'CNY',currencyVerified:false,url,
    observedSearch,conditionsVerified:true,partyParameterSupported:true,
    queryEvidence:{route_text:state.routeText,price_label:state.priceLabel,time_labels:state.timeLabels,
      party_source:'Business fields in the page-generated touchInterList request; absent infant count stays unknown',
      service_notice:state.serviceNotice,
      currency_basis:'CNY inferred from mainland Chinese site and yuan icon; no ISO currency field exposed'},
    collectionMethod:'rendered_mobile_search_cards',exhaustive:false}));
}

cli({site:'travel-price',name:'qunar-flight',access:'read',description:'Qunar mobile-web per-traveler flight fares and observed outbound search party',
  domain:'touch.qunar.com',strategy:Strategy.COOKIE,browser:true,navigateBefore:false,args:flightArgs,
  func:async(page,args)=>withPageActivity(page,async()=>{
    const url=qunarFlightUrl(args);await checkProblem(page);
    await page.startNetworkCapture('/flight/api/touchInterList');await navigate(page,url);
    let state,request;
    for(let i=0;i<25;i++) {
      await checkProblem(page);
      state=await page.evaluate('('+readQunarFlight.toString()+')()');
      request=qunarFlightRequest(await page.readNetworkCapture({retainIncomplete:true}))||request;
      if(state.cards.length&&request)return mapQunarFlight(state,request,args,url);
      await page.wait({time:1});
    }
    throw new CliError('UNVERIFIED_RESPONSE','Qunar mobile flight cards or observed request were unavailable'+
      (state?.serviceNotice?'; page notice: '+state.serviceNotice:''),'No dated quote was verified; this does not prove no flights');
  })
});
